/**
 * @param {number[][]} img1
 * @param {number[][]} img2
 * @return {number}
 */
var largestOverlap = function(img1, img2) {
    const n = img1.length;
    const set1 = new Set();
    const set2 = new Set();

    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            if (img1[i][j] === 1) set1.add([i, j]);
            if (img2[i][j] === 1) set2.add([i, j]);
        }
    }

    const map = new Map();
    let max = 0;

    for (const point1 of set1) {
        for (const point2 of set2) {
            const dx = point1[0] - point2[0];
            const dy = point1[1] - point2[1];

            const key = dx + ':' + dy;
            const count = (map.get(key) || 0) + 1;
            map.set(key, count);

            max = Math.max(max, count);
        }
    }

    return max;
};
